-- Bateria visual solicitada: cronograma de postagens do PET Educação (12/11/2026).
-- Somente as sete atividades da Semana 2 recuperadas com datas e títulos verificáveis.
-- Sem usuários fictícios, sem e-mails/notificações, sem mudança em demandas existentes.
-- Comissão: Legendas. overview_visible=0 oculta todos da Visão geral.
-- Prefixos de ID técnicos exclusivos permitem exclusão posterior sem afetar registros reais.
INSERT OR IGNORE INTO tasks (id,title,description,caption_text,registered_at,assignee_ids,commission_ids,commission_done,deadlines,status,archived_at,created_by,updated_by,created_at,updated_at,version,user_done,overview_visible,assignment_scope)
SELECT 'pet-cronograma-legendas-202611-01-mostra-robotica', '[TESTE] Mostra de robótica — fotos do evento de 06/11', '<p><strong>Teste visual do cronograma de postagens — Semana 2 (09–13/11/2026).</strong></p><p>Postagem de fotos da Mostra de Robótica, realizada na sexta-feira (06/11).</p><p>Responsável indicado no cronograma: Andreza.</p><p>Atividade vinculada somente à comissão Legendas; não aparece na Visão geral.</p>', '', '2026-11-09', '[]', '["legendas"]', '{}', '[{"id":"cronograma-1-1","label":"Prazo","dueAt":"2026-11-09T23:59:59","assigneeIds":[],"commissionCompleted":{},"completedAt":null},{"id":"cronograma-1-2","label":"Postagem","dueAt":"2026-11-09T23:59:59","assigneeIds":[],"commissionCompleted":{},"completedAt":null}]', 'pendente', NULL, a.id, a.id, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, '{}', 0, 'comissoes'
FROM users a WHERE a.id=(SELECT id FROM users WHERE role='admin' ORDER BY created_at LIMIT 1)
AND EXISTS (SELECT 1 FROM commissions WHERE id='legendas');

